import numpy as np
from scipy.optimize import minimize
import itertools

def get_min_diff(y):
    # y is the sorted logs
    # We need to pick 4 distinct indices from {0, 1, 2, 3, 4}
    # This function calculates the minimum |exp(y[e]-y[h]) - exp(y[g]-y[f])|
    # for all permutations (e, f, g, h) of 4 indices from {0, 1, 2, 3, 4}
    # However, the problem says e, f, g, h are distinct.
    # So we just need to pick 4 indices and then try all permutations.
    n = len(y)
    min_val = float('inf')
    for p in itertools.permutations(range(n), 4):
        e, f, g, h = p
        val = abs(np.exp(y[e] - y[h]) - np.exp(y[g] - y[f]))
        if val < min_val:
            min_val = val
    return min_val

def objective(y):
    return -get_min_diff(y)

best_min = 0
for i in range(100):
    y_start = np.sort(np.random.uniform(-2, 2, 5))
    res = minimize(objective, y_start, method='Nelder-Mead')
    if -res.fun > best_min:
        best_min = -res.fun
        best_y = res.x

print(f"Best min: {best_min}")
print(f"Best y: {best_y}")
